// Validate the request from EcoTrack and build the prompt.
// Throwing an error here makes the webhook fail, and EcoTrack then uses its built-in tips.
const body = $input.first().json.body || {};

const required = ['question', 'period', 'water', 'electricity'];
for (const key of required) {
  if (body[key] === undefined || body[key] === null) throw new Error(`Missing field: ${key}`);
}
if (typeof body.question !== 'string' || body.question.length < 3 || body.question.length > 500) {
  throw new Error('Invalid question');
}

const system = `You are EcoTrack's Resource Coach for a household in Namibia.
You receive a JSON summary of ESTIMATED water and electricity use, calculated from activities the household recorded. They are not meter readings.

Rules:
- Base every statement only on the supplied data. Quote figures exactly as given.
- Say the figures are estimates. If contains_demo_data is true, say it is a fictional demo household.
- Do not invent measurements, prices, tariffs, savings amounts or statistics. If costs_available is false, do not mention money amounts.
- Never guarantee a reduction in use or bills.
- Prefer low-cost, realistic household habits. Explain why each suggestion may help, using the data.
- If the data is too thin to answer, say so in the summary.
- Never claim to read meters or control appliances.
- No electrical, gas or plumbing repair instructions: for geysers, wiring or leaks, recommend a qualified professional.
- Plain, friendly English. No markdown.

Reply with ONLY a JSON object, no other text:
{"summary": "2-4 sentences answering the question", "recommendations": [{"title": "short action", "why": "1-2 sentences linked to the data", "resource": "water" | "electricity" | "both", "effort": "easy" | "moderate" | "hard"}], "data_note": "one sentence on what the data is based on"}
Give 2 to 4 recommendations.`;

const user = `Question: ${body.question}\n\nHousehold summary (JSON):\n${JSON.stringify(body, null, 2)}`;

return [{ json: { system, user } }];

// Check the LLM reply has exactly the shape EcoTrack expects.
// EcoTrack validates it again; anything wrong here falls back to built-in tips.
const reply = $input.first().json;
let text = (reply.content && reply.content[0] && reply.content[0].text) || '';
text = text.trim().replace(/^```(?:json)?/i, '').replace(/```$/, '').trim();

let data;
try { data = JSON.parse(text); } catch (e) { throw new Error('LLM did not return valid JSON'); }

const RES = ['water', 'electricity', 'both'];
const EFF = ['easy', 'moderate', 'hard'];
if (typeof data.summary !== 'string' || !Array.isArray(data.recommendations) || data.recommendations.length === 0) {
  throw new Error('LLM response missing summary or recommendations');
}

const recommendations = data.recommendations.slice(0, 5).map((r) => ({
  title: String(r.title || '').slice(0, 120),
  why: String(r.why || '').slice(0, 600),
  resource: RES.includes(r.resource) ? r.resource : 'both',
  effort: EFF.includes(r.effort) ? r.effort : 'easy',
})).filter((r) => r.title && r.why);
if (!recommendations.length) throw new Error('No usable recommendations');

return [{ json: {
  summary: data.summary.slice(0, 1200),
  recommendations,
  data_note: String(data.data_note || 'These figures are estimates based on recorded activities, not meter readings.').slice(0, 400),
} }];
